 public static void Validate(){checks=0;ValidateGraphicFactories();ValidatePreviewLifetime();ValidatePreviewIsolation();ValidateButtonContrast();ValidateDeckPresentation();var legacy=FloorSave.Parse("{\"Schema\":1,\"Crystals\":428,\"Step\":7,\"Checkpoint\":4}");Check(!legacy.TutorialCompleted&&legacy.Crystals==428&&legacy.Step==7,"missing tutorial field retains old profile");legacy.TutorialCompleted=true;var copy=FloorSave.Parse(JsonUtility.ToJson(legacy));Check(copy.TutorialCompleted&&copy.Crystals==428&&copy.Step==7,"tutorial completion round trips without progress migration");
  var lesson=new ElevatorTutorial();lesson.Landing(false,1);lesson.AtCheckpoint();Check(lesson.Stage==ElevatorTutorialStage.Perfect,"checkpoint cannot replace actual perfect");lesson.Landing(true,2);lesson.AtCheckpoint();lesson.Risk();lesson.Landing(true,5);lesson.AtCheckpoint();lesson.Banked();Check(lesson.Complete,"actual risk landing then banking completes");
  foreach(var size in new[]{new Vector2(375,627),new Vector2(393,759),new Vector2(430,839),new Vector2(734,343),new Vector2(809,372),new Vector2(280,580)})foreach(var lang in new[]{"de","en"})LayoutFixture(size,lang);Debug.Log("LIFT_MENU_EDITOR_PASS checks="+checks);
 }
 public static void ValidatePreviewIsolation(){var canvas=UiFactory.Canvas();try{
  var previews=new LiftScenePreview[4];previews[0]=LiftScenePreview.Create(canvas.transform,0).GetComponent<LiftScenePreview>();for(int i=1;i<4;i++){previews[i]=LiftScenePreview.CreateCity(canvas.transform,i-1).GetComponent<LiftScenePreview>();CheckCityOnly(previews[i]);}
  for(int i=0;i<previews.Length;i++){var camera=previews[i].SceneRoot.GetComponentInChildren<Camera>();Check(camera.cullingMask==(1<<LiftScenePreview.PreviewLayer),"preview camera retains gameplay-excluded layer");for(int j=0;j<previews.Length;j++)if(i!=j){Check(Vector3.Distance(previews[i].SceneRoot.transform.position,previews[j].SceneRoot.transform.position)>=128,"simultaneous preview roots have independent spatial slots");var planes=GeometryUtility.CalculateFrustumPlanes(camera);foreach(var renderer in previews[j].SceneRoot.GetComponentsInChildren<Renderer>())if(renderer.gameObject.activeInHierarchy)Check(!GeometryUtility.TestPlanesAABB(planes,renderer.bounds),"preview camera cannot render another live chapter or cabin");}}
  var location=previews[1].SceneRoot.transform.position;var survivor=previews[0].SceneRoot;UnityEngine.Object.DestroyImmediate(previews[1].gameObject);var replacement=LiftScenePreview.CreateCity(canvas.transform,2).GetComponent<LiftScenePreview>();Check(replacement.SceneRoot.transform.position==location,"destroyed preview slot is recycled");Check(survivor!=null&&survivor.activeSelf,"disposing chapter preserves another live preview");
  for(int cycle=0;cycle<8;cycle++){var position=replacement.SceneRoot.transform.position;var texture=replacement.texture;UnityEngine.Object.DestroyImmediate(replacement.gameObject);Check(texture==null,"recycled preview releases its render target");replacement=LiftScenePreview.CreateCity(canvas.transform,cycle%3).GetComponent<LiftScenePreview>();CheckCityOnly(replacement);Check(replacement.SceneRoot.transform.position==position,"repeated preview closes do not grow spatial allocation");}
 }finally{UnityEngine.Object.DestroyImmediate(canvas.gameObject);}}
 static void CheckCityOnly(LiftScenePreview preview){Check(preview.SceneRoot.transform.Find("ChapterCityKit")!=null,"chapter preview retains its actual city geometry");foreach(var node in preview.SceneRoot.GetComponentsInChildren<Transform>(true))Check(node.name!="CopperLiftCabin"&&node.name!="VerticalLiftRail"&&node.name!="ArchitecturalFloorBay"&&node.name!="LobbyLanding"&&node.name!="HoodieRunner","chapter preview never constructs unused cabin/rail/bay/runner "+node.name);Check(preview.SceneRoot.GetComponentsInChildren<Kamilunavo.OneMoreFloor.Visuals.RunnerAnimator>(true).Length==0,"chapter preview retains no runner instance");}
 static void ValidatePreviewLifetime(){var canvas=UiFactory.Canvas();try{var pane=LiftScenePreview.Create(canvas.transform,0);var preview=pane.GetComponent<LiftScenePreview>();var scene=preview.SceneRoot;var target=preview.texture;Check(scene.GetComponentsInChildren<Collider>().Length==0,"menu preview has no gameplay collisions");Check(scene.transform.Find("CopperLiftCabin")!=null,"preview shares actual cabin kit");foreach(var renderer in scene.GetComponentsInChildren<Renderer>())Check(renderer.gameObject.layer==LiftScenePreview.PreviewLayer,"preview isolated from shipping camera");UnityEngine.Object.DestroyImmediate(pane.gameObject);Check(scene==null&&target==null,"closing lobby disposes render texture and scene geometry");}finally{UnityEngine.Object.DestroyImmediate(canvas.gameObject);}}
 static void ValidateDeckPresentation(){var root=new GameObject("DeckPresentationProbe");try{Kamilunavo.OneMoreFloor.Visuals.PlatformArt.Build(root.transform,4,0);Kamilunavo.OneMoreFloor.Visuals.LiftArchitecture.Rails(root.transform);Kamilunavo.OneMoreFloor.Visuals.LiftArchitecture.Bay(root.transform,4);Check(root.transform.Find("CopperLiftCabin")!=null&&root.transform.Find("ArchitecturalFloorBay")!=null,"cabin and cream architectural bay present");int rails=0;foreach(Transform child in root.transform)if(child.name=="VerticalLiftRail")rails++;Check(rails==2,"two actual lift guide rails");Check(root.GetComponentsInChildren<Collider>().Length==1,"industrial decoration adds no gameplay collision");Check(root.GetComponentInChildren<TextMesh>().transform.localRotation==Quaternion.identity,"architectural floor label faces the camera without mirrored glyphs");Check(root.transform.Find("ServiceInlay")!=null&&root.transform.Find("CarriageRoller")!=null&&root.transform.Find("LiftControlDisplay")!=null,"authored vent/carriage/control kit exists");var collision=root.GetComponentInChildren<BoxCollider>();Check(collision.size==new Vector3(4.6f,.70f,3.6f)&&collision.center==new Vector3(0,.25f,0),"landing surface dimensions remain authoritative");}finally{UnityEngine.Object.DestroyImmediate(root);}}
 static void ValidateButtonContrast(){var canvas=UiFactory.Canvas();try{foreach(var background in new[]{new Color(.07f,.12f,.17f),new Color(.06f,.63f,.76f),new Color(1,.73f,.12f),new Color(1,.4f,.06f)}){var button=UiFactory.Button(canvas.transform,"ContrastProbe","READABLE",background,Color.white,Vector2.zero,Vector2.one,null);CheckButtonContrast(button,"factory");UnityEngine.Object.DestroyImmediate(button.gameObject);}}finally{UnityEngine.Object.DestroyImmediate(canvas.gameObject);}}
 static float Contrast(Color a,Color b){float Linear(float c)=>c<=.04045f?c/12.92f:Mathf.Pow((c+.055f)/1.055f,2.4f);float L(Color c)=>.2126f*Linear(c.r)+.7152f*Linear(c.g)+.0722f*Linear(c.b);return (Mathf.Max(L(a),L(b))+.05f)/(Mathf.Min(L(a),L(b))+.05f);}
 static void CheckButtonContrast(Button button,string pose){var image=button.GetComponent<Image>();foreach(var state in new[]{button.colors.normalColor,button.colors.highlightedColor,button.colors.pressedColor,button.colors.selectedColor,button.colors.disabledColor}){Color surface=image.color*state*button.colors.colorMultiplier;surface.a=1;foreach(var text in button.GetComponentsInChildren<Text>())if(!string.IsNullOrWhiteSpace(text.text))Check(Contrast(surface,text.color)>=4.5f,pose+" all button states readable "+button.name+"/"+text.name);}}
 static void ValidateGraphicFactories(){var canvas=UiFactory.Canvas();try{var pane=UiFactory.Panel(canvas.transform,"ClippedGraphicProbe",Color.white,Vector2.zero,Vector2.one);pane.gameObject.AddComponent<RectMask2D>();UiFactory.Label(pane,"Label","Graphic probe",16,Vector2.zero,Vector2.one,TextAnchor.MiddleCenter,Color.white);HudIcons.Add(pane,HudIcons.Kind.Menu);LiftTowerGraphic.Create(pane,0);ScenicCityGraphic.Create(pane,0);Kamilunavo.OneMoreFloor.Input.VirtualJoystick.Create(pane,Vector2.zero,Vector2.one);Kamilunavo.OneMoreFloor.Input.PressButton.Create(pane,"Circle",Vector2.zero,Vector2.one);Kamilunavo.OneMoreFloor.Input.PressButton.Create(pane,"Wide",Vector2.zero,Vector2.one,true);foreach(var graphic in canvas.GetComponentsInChildren<Graphic>())Check(graphic.GetComponent<CanvasRenderer>()!=null,"graphic factory owns CanvasRenderer "+graphic.name);Canvas.ForceUpdateCanvases();}finally{UnityEngine.Object.DestroyImmediate(canvas.gameObject);}}
