   var card=(RectTransform)safe.Find("ModalBackdrop/ModalCard");var viewport=(RectTransform)card.Find("Viewport");Check(!viewport.GetComponent<ScrollRect>().vertical,size+" home uses fixed hierarchy");var content=viewport.Find("Content");Check(content.Find("TowerPreview/LiftElevation")!=null,size+" authored lift preview exists");Check(content.Find("TowerPreview/LiftElevation").GetComponent<LiftScenePreview>()!=null,size+" lobby renders the real 3D cabin");Check(card.GetComponent<Image>().color.r>.9f,size+" warm ivory lobby surface");for(int realm=0;realm<3;realm++)Check(content.Find("Realm"+realm+"/ChapterIllustration").GetComponent<LiftScenePreview>()!=null,size+" chapter has real rendered city architecture "+realm);
