   Rect usable=UiMetrics.ScreenRect(safe),body=UiMetrics.ScreenRect(viewport);var buttons=card.GetComponentsInChildren<Button>();foreach(var b in buttons){CheckButtonContrast(b,size+" "+language+" home");Rect r=UiMetrics.ScreenRect((RectTransform)b.transform);Check(r.width/3>=47.999f&&r.height/3>=47.999f,size+" "+language+" >=48 points "+b.name);Check(Inside(usable,r),size+" safe bounds "+b.name);if(b.transform.IsChildOf(content))Check(Inside(body,r),size+" visible without scrolling "+b.name);}
