   void CheckPage(string page){var current=(RectTransform)safe.Find("ModalBackdrop/ModalCard");if(page=="checkpoint"){Check(current.GetComponent<Image>().color.r>.9f,"risk uses readable ivory sheet");Check(current.rect.height<= (size.x>size.y?230:320),size+" risk card has no empty tall modal");Check(Inside(usable,UiMetrics.ScreenRect(current)),size+" risk sheet stays in safe region");Check(current.Find("Viewport/Content/FloorComparison")!=null,"current and next architectural previews present");Check(Inside(UiMetrics.ScreenRect((RectTransform)current.Find("Viewport")),UiMetrics.ScreenRect((RectTransform)current.Find("Viewport/Content/FloorComparison"))),"risk comparison wholly visible");}foreach(var button in current.GetComponentsInChildren<Button>()){CheckButtonContrast(button,size+" "+language+" "+page);Rect r=UiMetrics.ScreenRect((RectTransform)button.transform);Check(r.width/3>=47.999f&&r.height/3>=47.999f,size+" "+page+" >=48 points "+button.name);if(page=="checkpoint"||page=="banked")Check(Inside(UiMetrics.ScreenRect(current.Find("Viewport") as RectTransform),r)||!button.transform.IsChildOf(current.Find("Viewport")),size+" "+page+" decision remains in card");}}
  }finally{UiMetrics.QaPointScale=null;if(canvas!=null)UnityEngine.Object.DestroyImmediate(canvas.gameObject);UnityEngine.Object.DestroyImmediate(root);}}
 static bool Inside(Rect outer,Rect inner)=>inner.xMin>=outer.xMin-.5f&&inner.yMin>=outer.yMin-.5f&&inner.xMax<=outer.xMax+.5f&&inner.yMax<=outer.yMax+.5f;
